-- Move any NFT bonus that was credited to ordinary points (before the separate bonus balance existed) into bonus_points. Only wallets with claims; capped at their current balance.
UPDATE `agents` SET `bonus_points`=CAST((CASE WHEN CAST(COALESCE(`points_exact`,CAST(`points` AS text)) AS bigint)<(SELECT CAST(COALESCE(SUM(`c`.`amount`),0) AS bigint) FROM `nft_bonus_claims` `c` WHERE `c`.`wallet`=`agents`.`wallet`) THEN CAST(COALESCE(`points_exact`,CAST(`points` AS text)) AS bigint) ELSE (SELECT CAST(COALESCE(SUM(`c`.`amount`),0) AS bigint) FROM `nft_bonus_claims` `c` WHERE `c`.`wallet`=`agents`.`wallet`) END) AS text),`points_exact`=CASE WHEN `points_exact` IS NULL THEN NULL ELSE CAST(CAST(`points_exact` AS bigint)-(CASE WHEN CAST(COALESCE(`points_exact`,CAST(`points` AS text)) AS bigint)<(SELECT CAST(COALESCE(SUM(`c`.`amount`),0) AS bigint) FROM `nft_bonus_claims` `c` WHERE `c`.`wallet`=`agents`.`wallet`) THEN CAST(COALESCE(`points_exact`,CAST(`points` AS text)) AS bigint) ELSE (SELECT CAST(COALESCE(SUM(`c`.`amount`),0) AS bigint) FROM `nft_bonus_claims` `c` WHERE `c`.`wallet`=`agents`.`wallet`) END) AS text) END,`points`=CASE WHEN `points`>(CASE WHEN CAST(COALESCE(`points_exact`,CAST(`points` AS text)) AS bigint)<(SELECT CAST(COALESCE(SUM(`c`.`amount`),0) AS bigint) FROM `nft_bonus_claims` `c` WHERE `c`.`wallet`=`agents`.`wallet`) THEN CAST(COALESCE(`points_exact`,CAST(`points` AS text)) AS bigint) ELSE (SELECT CAST(COALESCE(SUM(`c`.`amount`),0) AS bigint) FROM `nft_bonus_claims` `c` WHERE `c`.`wallet`=`agents`.`wallet`) END) THEN `points`-(CASE WHEN CAST(COALESCE(`points_exact`,CAST(`points` AS text)) AS bigint)<(SELECT CAST(COALESCE(SUM(`c`.`amount`),0) AS bigint) FROM `nft_bonus_claims` `c` WHERE `c`.`wallet`=`agents`.`wallet`) THEN CAST(COALESCE(`points_exact`,CAST(`points` AS text)) AS bigint) ELSE (SELECT CAST(COALESCE(SUM(`c`.`amount`),0) AS bigint) FROM `nft_bonus_claims` `c` WHERE `c`.`wallet`=`agents`.`wallet`) END) ELSE 0 END WHERE EXISTS(SELECT 1 FROM `nft_bonus_claims` `c` WHERE `c`.`wallet`=`agents`.`wallet`) AND length(COALESCE(`points_exact`,CAST(`points` AS text)))<18;